export const AR_FALLBACK_MESSAGE='No se pudo abrir el visor AR nativo. Esto no confirma que el teléfono sea incompatible: revisa Google Play Services para AR, sus actualizaciones y si Chrome permitió abrir la aplicación. No se activó una cámara dentro de ONE16.';
export function bindAndroidLaunch({links,status,fallbackNotice,search='',eventRoot,documentRef,timer=setTimeout,clearTimer=clearTimeout}){
 let timeout;const fallback=new URLSearchParams(search).get('ar_fallback')==='1';if(fallback){fallbackNotice.hidden=false;fallbackNotice.textContent=AR_FALLBACK_MESSAGE;status.textContent='El intento volvió al sitio sin abrir AR.'}
 const click=()=>{clearTimer(timeout);status.textContent='Solicitando abrir el visor nativo… Si aparece una confirmación de Chrome, elige Abrir. La cámara todavía no está confirmada.';timeout=timer(()=>{if(documentRef.visibilityState!=='hidden')status.textContent='Si no se abrió otro visor, el lanzamiento no está confirmado. Consulta el aviso de compatibilidad o prueba la alternativa 3D/AR.'},2500)};
 for(const link of links)link.addEventListener('click',click);const hide=()=>{if(documentRef.visibilityState==='hidden')clearTimer(timeout)};eventRoot?.addEventListener('visibilitychange',hide);
 return{dispose(){clearTimer(timeout);for(const link of links)link.removeEventListener('click',click);eventRoot?.removeEventListener('visibilitychange',hide)}};
}
export async function checkPassportAsset(fetcher=fetch){const response=await fetcher('./assets/passport.glb',{cache:'no-cache'});if(!response.ok)throw Error(`HTTP ${response.status}`);const data=await response.arrayBuffer(),v=new DataView(data);if(data.byteLength<20||v.getUint32(0,true)!==0x46546c67||v.getUint32(4,true)!==2||v.getUint32(8,true)!==data.byteLength)throw Error('La respuesta no es un GLB 2.0 completo');return{bytes:data.byteLength,type:response.headers.get('content-type')||'no indicado',url:response.url}}
